# Metadata Reconstruction Tool - runnable demo (JAH-ATK159-000001)
import re
from datetime import datetime
RANK = 1
SIG = False
SAMPLE = [('2024-03-15_field-trip_042.jpg', {'author': 'J. Rivera', 'camera': 'Nikon D750'}), ('IMG_0043.jpg', {'date_taken': '2024-03-15'}), ('scan_007.tif', {})]  # (filename, embedded dict)
def from_name(fn):
    m = re.search(r"(\d{4})[-_](\d{2})[-_](\d{2})", fn)
    date = "%s-%s-%s" % m.groups() if m else None
    m2 = re.search(r"_(\d{3,4})\.", fn)
    seq = m2.group(1) if m2 else None
    return date, seq
for fn, emb in SAMPLE:
    rec = {"file": fn}
    d, seq = from_name(fn)
    ev = []
    if d: rec["date_guess"] = d; ev.append(("filename", 0.6))
    if seq: rec["sequence"] = seq; ev.append(("filename", 0.7))
    for k in ("author", "camera", "title"):
        if emb.get(k): rec[k] = emb[k]; ev.append(("embedded", 0.95))
    rec["date"] = emb.get("date_taken") or d or "unknown"
    print(fn, "->", {k: v for k, v in rec.items() if k != "file"})
    if RANK >= 2: print("   evidence:", ev)
    if RANK >= 3:
        conf = sum(w for _, w in ev)/len(ev) if ev else 0
        print("   mean evidence confidence: %.2f" % conf)
if SIG:
    print("Signature lineage stamp: JAH-SIG-META-" + "JAH-ATK159-000001")
print("record:", "JAH-ATK159-000001", "OK")

